package manager

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/http/httptest"
	"os"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/NahaNCode/nahan-core/api"
	"github.com/NahaNCode/nahan-core/api/nahan"
	xnet "github.com/xtls/xray-core/common/net"
	"github.com/xtls/xray-core/core"
	"github.com/xtls/xray-core/features/outbound"
	"github.com/xtls/xray-core/infra/conf"
)

// Uses effective authorization snapshots generated by the PostgreSQL backend integration test.
func TestConnectionGroupsAgainstRealXrayClients(t *testing.T) {
	path := os.Getenv("NAHAN_GROUP_TEST_FIXTURE")
	if path == "" {
		t.Skip("Run backend group integration first and supply its contract fixture")
	}
	var fixture struct {
		Nodes []struct {
			ID     int                    `json:"id"`
			CoreID string                 `json:"core_id"`
			Server map[string]interface{} `json:"server"`
		} `json:"nodes"`
		Initial, Changed map[string]json.RawMessage
		Services         []struct {
			ID         int    `json:"id"`
			Credential string `json:"credential"`
		} `json:"services"`
	}
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if err = json.Unmarshal(data, &fixture); err != nil {
		t.Fatal(err)
	}
	if len(fixture.Nodes) != 9 || len(fixture.Services) != 3 {
		t.Fatal("Acceptance requires nine entries and three independent service credentials")
	}
	var phase atomic.Int32
	var mu sync.Mutex
	acknowledged := map[int]int64{}
	ports := map[int]int{}
	configs := map[int]map[string]interface{}{}
	for _, node := range fixture.Nodes {
		listener, err := net.Listen("tcp", "127.0.0.1:0")
		if err != nil {
			t.Fatal(err)
		}
		ports[node.ID] = listener.Addr().(*net.TCPAddr).Port
		listener.Close()
		config := node.Server["server"].(map[string]interface{})
		config["listeningport"] = strconv.Itoa(ports[node.ID])
		configs[node.ID] = node.Server
	}
	panel := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		var node int
		var resource string
		parts := strings.Split(strings.Trim(r.URL.Path, "/"), "/")
		if len(parts) != 6 {
			http.NotFound(w, r)
			return
		}
		fmt.Sscanf(parts[4], "%d", &node)
		resource = parts[5]
		if r.Header.Get("Authorization") != "Bearer group-qa" {
			w.WriteHeader(401)
			return
		}
		if phase.Load() == 3 {
			w.WriteHeader(503)
			w.Write([]byte(`{"error":"offline"}`))
			return
		}
		switch resource {
		case "server":
			json.NewEncoder(w).Encode(configs[node])
		case "subscriptions":
			snapshot := fixture.Initial[strconv.Itoa(node)]
			if phase.Load() > 0 {
				snapshot = fixture.Changed[strconv.Itoa(node)]
			}
			if phase.Load() == 2 {
				var document map[string]interface{}
				json.Unmarshal(snapshot, &document)
				document["leaseSeconds"] = 2
				json.NewEncoder(w).Encode(document)
			} else {
				w.Write(snapshot)
			}
		case "heartbeat":
			var h struct {
				Revision int64 `json:"authorizationRevision"`
				Synced   bool  `json:"servicesSynced"`
			}
			json.NewDecoder(r.Body).Decode(&h)
			if h.Synced {
				mu.Lock()
				acknowledged[node] = h.Revision
				mu.Unlock()
			}
			w.Write([]byte(`{"ret":1}`))
		default:
			w.Write([]byte(`{"ret":1}`))
		}
	}))
	defer panel.Close()
	managers := map[string]*Manager{}
	for _, node := range fixture.Nodes {
		manager := managers[node.CoreID]
		if manager == nil {
			manager = New(&Config{LogConfig: &LogConfig{Level: "none"}})
			managers[node.CoreID] = manager
		}
		client := nahan.New(&api.Config{Protocol: "nahan-v1", NodeID: node.ID, APIHost: panel.URL, Key: "group-qa", Timeout: 1})
		manager.managerConfig.NodesConfig = append(manager.managerConfig.NodesConfig, &NodesConfig{PreparedAPI: client})
	}
	for _, manager := range managers {
		if err := manager.StartChecked(); err != nil {
			t.Fatal(err)
		}
		defer manager.Close()
	}
	// Only the isolated QA instances may reach the loopback echo server.
	// Keep Xray's production private-network protection unchanged.
	allowEcho := func() {
		for _, node := range fixture.Nodes {
			manager := managers[node.CoreID]
			tag := fmt.Sprintf("Vless_%d_%d", ports[node.ID], node.ID)
			settings := json.RawMessage(`{"finalRules":[{"action":"allow","ip":["127.0.0.1/32"]}]}`)
			config, err := (&conf.OutboundDetourConfig{Tag: tag, Protocol: "freedom", Settings: &settings}).Build()
			if err != nil {
				t.Fatal(err)
			}
			if err = manager.Server.GetFeature(outbound.ManagerType()).(outbound.Manager).RemoveHandler(context.Background(), tag); err != nil {
				t.Fatal(err)
			}
			if err = core.AddOutboundHandler(manager.Server, config); err != nil {
				t.Fatal(err)
			}
		}
	}
	allowEcho()
	echo, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	defer echo.Close()
	go func() {
		for {
			conn, err := echo.Accept()
			if err != nil {
				return
			}
			go func() { defer conn.Close(); io.Copy(conn, conn) }()
		}
	}()
	target := xnet.TCPDestination(xnet.ParseAddress("127.0.0.1"), xnet.Port(echo.Addr().(*net.TCPAddr).Port))
	connect := func(node int, credential string) (*core.Instance, net.Conn, error) {
		document := fmt.Sprintf(`{"log":{"loglevel":"none"},"outbounds":[{"protocol":"vless","settings":{"vnext":[{"address":"127.0.0.1","port":%d,"users":[{"id":%q,"encryption":"none"}]}]},"streamSettings":{"network":"raw","security":"none"}}]}`, ports[node], credential)
		config, err := core.LoadConfig("json", strings.NewReader(document))
		if err != nil {
			return nil, nil, err
		}
		client, err := core.New(config)
		if err != nil {
			return nil, nil, err
		}
		if err = client.Start(); err != nil {
			client.Close()
			return nil, nil, err
		}
		conn, err := core.Dial(context.Background(), client, target)
		if err != nil {
			client.Close()
			return nil, nil, err
		}
		return client, conn, nil
	}
	check := func(node int, credential string) bool {
		client, conn, err := connect(node, credential)
		if err != nil {
			return false
		}
		defer client.Close()
		defer conn.Close()
		timer := time.AfterFunc(time.Second, func() { conn.Close(); client.Close() })
		defer timer.Stop()
		if _, err = conn.Write([]byte("group-qa")); err != nil {
			return false
		}
		response := make([]byte, 8)
		_, err = io.ReadFull(conn, response)
		return err == nil && string(response) == "group-qa"
	}
	positive, negative := 0, 0
	for serviceIndex, service := range fixture.Services {
		for node := 1; node <= 9; node++ {
			expected := (node-1)/3 == serviceIndex
			actual := check(node, service.Credential)
			if expected != actual {
				t.Fatalf("service %d entry %d: expected acceptance %v, got %v", service.ID, node, expected, actual)
			}
			if actual {
				positive++
			} else {
				negative++
			}
		}
	}
	if positive != 9 || negative != 18 {
		t.Fatal("Incomplete authorization matrix")
	}
	liveClient, live, err := connect(1, fixture.Services[0].Credential)
	if err != nil {
		t.Fatal(err)
	}
	defer liveClient.Close()
	defer live.Close()
	live.Write([]byte("group-qa"))
	payload := make([]byte, 8)
	if _, err = io.ReadFull(live, payload); err != nil {
		t.Fatal(err)
	}
	phase.Store(1)
	deadline := time.Now().Add(20 * time.Second)
	for time.Now().Before(deadline) {
		mu.Lock()
		rev := acknowledged[1]
		mu.Unlock()
		var document struct {
			Revision int64 `json:"authorizationRevision"`
		}
		json.Unmarshal(fixture.Changed["1"], &document)
		if rev == document.Revision {
			break
		}
		time.Sleep(100 * time.Millisecond)
	}
	if check(1, fixture.Services[0].Credential) {
		t.Fatal("Removed group member still accepted credential")
	}
	if !check(4, fixture.Services[0].Credential) || !check(4, fixture.Services[1].Credential) {
		t.Fatal("Explicit shared member rejected an entitled service")
	}
	if !check(2, fixture.Services[0].Credential) {
		t.Fatal("Removal revoked another authorized entry")
	}
	closed := make(chan error, 1)
	go func() { _, err := live.Read(payload); closed <- err }()
	select {
	case err := <-closed:
		if err == nil {
			t.Fatal("Revoked stream still readable")
		}
	case <-time.After(2 * time.Second):
		t.Fatal("Removing membership did not close existing connection")
	}
	phase.Store(2)
	time.Sleep(16 * time.Second)
	phase.Store(3)
	time.Sleep(3 * time.Second)
	if check(2, fixture.Services[0].Credential) {
		t.Fatal("Offline core accepted expired authorization lease")
	}
	phase.Store(1)
	time.Sleep(16 * time.Second)
	if !check(2, fixture.Services[0].Credential) {
		t.Fatal("Core did not recover authorization after panel returned")
	}
	for _, manager := range managers {
		manager.Close()
		if err := manager.StartChecked(); err != nil {
			t.Fatal(err)
		}
	}
	allowEcho()
	if check(1, fixture.Services[0].Credential) || check(9, fixture.Services[0].Credential) {
		t.Fatal("Restart restored unauthorized group credentials")
	}
	if !check(2, fixture.Services[0].Credential) || !check(4, fixture.Services[1].Credential) || !check(9, fixture.Services[2].Credential) {
		t.Fatal("Restart lost authorized group credentials")
	}
	t.Log("PASS: 9 authorized / 18 unauthorized real Xray connections, shared entry, live revocation, offline expiry, recovery and restart across two cores")
}
